package com.api.server

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.nio.ByteBuffer
import java.lang.reflect.Method
import sun.misc.Unsafe

object NativeMemoryPool {
  private val unsafe: Unsafe = {
    val f = classOf[Unsafe].getDeclaredField("theUnsafe")
    f.setAccessible(true)
    f.get(null).asInstanceOf[Unsafe]
  }

  private val poolSize: Long = 4096L
  private val baseAddress: Long = unsafe.allocateMemory(poolSize)
  private var offset: Long = 0L

  def allocate(size: Int): Long = synchronized {
    if (offset + size > poolSize) {
      offset = 0L // wrap around - reuse pool
    }
    val addr = baseAddress + offset
    offset += size
    addr
  }

  def write(addr: Long, data: Array[Byte]): Unit = {
    var i = 0
    while (i < data.length) {
      unsafe.putByte(addr + i, data(i))
      i += 1
    }
  }

  def read(addr: Long, length: Int): Array[Byte] = {
    val result = new Array[Byte](length)
    var i = 0
    while (i < length) {
      result(i) = unsafe.getByte(addr + i)
      i += 1
    }
    result
  }

  def writeReturnAddress(addr: Long, target: Long): Unit = {
    unsafe.putLong(addr, target)
  }
}

case class RequestContext(sessionId: String, payload: Array[Byte], callbackAddr: Long)

trait RequestHandler {
  def handle(ctx: RequestContext)(implicit ec: ExecutionContext): Future[Array[Byte]]
}

class BufferOverflowHandler extends RequestHandler {
  private val maxPayloadSize = 256
  private val headerSize = 8
  private val metadataSize = 16

  override def handle(ctx: RequestContext)(implicit ec: ExecutionContext): Future[Array[Byte]] = Future {
    val bufferAddr = NativeMemoryPool.allocate(maxPayloadSize + headerSize)

    // Write header (contains return/callback address for async completion)
    NativeMemoryPool.writeReturnAddress(bufferAddr, ctx.callbackAddr)

    // Write payload after header - NO bounds check on payload length
    // If payload.length > maxPayloadSize, it overwrites adjacent memory
    val dataStart = bufferAddr + headerSize
    NativeMemoryPool.write(dataStart, ctx.payload)

    // Read back processed data
    NativeMemoryPool.read(dataStart, math.min(ctx.payload.length, maxPayloadSize))
  }
}

class AsyncDispatcher {
  private val handlers = Map[String, RequestHandler](
    "process" -> new BufferOverflowHandler()
  )

  private val completionCallbacks = new java.util.concurrent.ConcurrentHashMap[String, Long]()

  def registerCallback(sessionId: String, addr: Long): Unit = {
    completionCallbacks.put(sessionId, addr)
  }

  def dispatch(route: String, sessionId: String, payload: Array[Byte]): Future[Array[Byte]] = {
    val callbackAddr = completionCallbacks.getOrDefault(sessionId, 0L)
    val ctx = RequestContext(sessionId, payload, callbackAddr)

    handlers.get(route) match {
      case Some(handler) => handler.handle(ctx)
      case None => Future.failed(new RuntimeException(s"No handler for $route"))
    }
  }
}

object ApiServer {
  val dispatcher = new AsyncDispatcher()

  def handleRequest(route: String, sessionId: String, rawPayload: Array[Byte]): Future[Array[Byte]] = {
    // Validate session exists
    if (sessionId == null || sessionId.isEmpty) {
      return Future.failed(new IllegalArgumentException("Invalid session"))
    }

    // Route validation
    if (!route.matches("[a-z]+")) {
      return Future.failed(new IllegalArgumentException("Invalid route"))
    }

    // Note: payload size is NOT validated here - delegated to handler
    // The handler's internal buffer is only 256 bytes but accepts arbitrary input
    dispatcher.dispatch(route, sessionId, rawPayload)
  }

  def main(args: Array[String]): Unit = {
    dispatcher.registerCallback("session-1", 0x41414141L)

    // Simulate normal request
    val normalPayload = "Hello, World!".getBytes
    handleRequest("process", "session-1", normalPayload)

    // An attacker can send payload > 256 bytes to overflow into adjacent
    // memory pool allocations, overwriting return addresses/callback pointers
    // that get invoked during async completion - classic ROP gadget setup
  }
}
